    "viz_ov_stack_spl": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "**Query \u00b7 OBTS 01 - Stack non-Apple code that executed**\n```\nindex=macos sourcetype=macos:eslogger es_event=exec target_signer!=apple\n| stats count dc(host_short) AS hosts values(host_short) AS on values(process_name) AS launched_by by target_signer target_team_id target_path\n| sort target_signer count\n```"
      }
    },
    "viz_ov_stack": {
      "type": "splunk.table",
      "title": "Non-Apple code that executed",
