    "viz_amos_4_spl": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "**Query \u00b7 OBTS AMOS 4 - Keychain reader egress in Zeek**\n```\nindex=macos sourcetype=macos:eslogger es_event=open file_path=\"*/Library/Keychains/*\" process_platform=false process_team_id=none\n| eval src_ip=host_ip, keychain_time=_time, keychain_reader=process_path\n| fields src_ip keychain_time keychain_reader\n| append [ search index=zeek (sourcetype=bro:conn:json OR sourcetype=bro:ssl:json) NOT id.resp_h=10.* NOT id.resp_p=53 | eval src_ip='id.orig_h' ]\n| eventstats values(keychain_time) AS keychain_times values(keychain_reader) AS keychain_reader by src_ip\n| where isnotnull(uid) AND isnotnull(keychain_times)\n| eval keychain_time=mvindex(mvmap(keychain_times, if(_time - keychain_times >= -30 AND _time - keychain_times <= 120, keychain_times, null())), 0)\n| where isnotnull(keychain_time)\n| stats min(_time) AS first_seen values(server_name) AS sni sum(orig_bytes) AS bytes_out sum(resp_bytes) AS bytes_in values(keychain_reader) AS keychain_reader min(keychain_time) AS keychain_time by uid src_ip id.resp_h id.resp_p\n| eval seconds_after_keychain=round(first_seen-keychain_time, 3), first_seen=strftime(first_seen, \"%F %T.%3N\")\n| table first_seen seconds_after_keychain src_ip id.resp_h id.resp_p sni bytes_out bytes_in uid keychain_reader\n```"
      }
